package net.civeira.phylax.features.access.userconsentedscopes.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class UserAgentVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property user agent of user consented scopes ")
  void test_user_agent_v_o_builder() {
    Assertions.assertFalse(UserAgentVO.nullValue().getUserAgent().isPresent(),
        "A empty vo should have a null value");
    Assertions.assertFalse(UserAgentVO.tryFrom(null).getUserAgent().isPresent(),
        "With a null value, no present result");
    Assertions.assertEquals("one", UserAgentVO.from("one").getUserAgent().orElse(null));
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> UserAgentVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + "one" + "]", UserAgentVO.from("one").toString());
  }
}
